import{_ as t}from"./chunks/architecture.CSAesduY.js";import{_ as a,c as n,a2 as i,o}from"./chunks/framework.BO4SuroD.js";const g=JSON.parse('{"title":"CUI Development: Start with Services, Not Conversations","description":"","frontmatter":{},"headers":[],"relativePath":"reference/essentials/3layers.md","filePath":"reference/essentials/3layers.md","lastUpdated":1737229990000}'),r={name:"reference/essentials/3layers.md"};function s(c,e,l,h,d,p){return o(),n("div",null,e[0]||(e[0]=[i('<h1 id="cui-development-start-with-services-not-conversations" tabindex="-1">CUI Development: Start with Services, Not Conversations <a class="header-anchor" href="#cui-development-start-with-services-not-conversations" aria-label="Permalink to &quot;CUI Development: Start with Services, Not Conversations&quot;">​</a></h1><p>Businesses allocate resources to develop conversational user interface (CUI) applications like chatbots and agents because they aim to provide conversational access to their services. Conversational interfaces enable users to interact with the business through natural language, making the process more intuitive and accessible.</p><p>In this context, a service represents a specific business capability or functionality that delivers value to users. These services are often implemented as a collection of Application Programming Interfaces (APIs), which are functions that can be invoked by other software systems. Each API is essentially a compount type, defined by a schema that specifies the input and output parameters, along with their respective data types. The goal of a Conversational User Interface (CUI) is to gather values of the respective types for each required input parameter through conversation, enabling the API to be triggered and the service to be delivered to the user.</p><p>This perspecive suggests that we can develop CUI components or applications in a schema-grounded approach. And this approach is best described if we model CUI development in three layers</p><p><img src="'+t+'" alt="three layers"></p><h4 id="service-schema" tabindex="-1">Service schema <a class="header-anchor" href="#service-schema" aria-label="Permalink to &quot;Service schema&quot;">​</a></h4><p>Services are typically implemented in the back-end, and exposed by a set of API functions. These functions can be defined by some API scheme, mainly details the function signature, including data types for their parameters and returns. While there are new APIs specifically designed because of chatbots, all service APIs can be shared between different frontends: including web and mobile apps. So one can safely assume the back-end service is already available, or it can be taken care of as a separate concern.</p><h4 id="interaction-logic" tabindex="-1">Interaction logic <a class="header-anchor" href="#interaction-logic" aria-label="Permalink to &quot;Interaction logic&quot;">​</a></h4><p>In case user does not provide all the information in one go, or users change their mind in the middle of conversion, chatbot need to conduct conversation to gather required information to invoke service API. The interaction logic is typically language-independent to ensure a consistent user experience regardless of the language used to interact with the chatbot.</p><p>Naturally, the interaction logic layer interact with back-end through well-defined APIs. For example, when prompting movie goers for their movie preference, it is a good idea to provide candidates list that is still available for the day, or lets user know if their choice of items ran out, all by making use of service APIs.</p><p>The functionalities of an API are already described using a language like OpenAPI. The challenge is how to invoke these functions naturally using conversational interaction logic. Most CUI platforms only support intent with entity slots, which makes it difficult to interact with functions that have parameters of composite types, list-contained types, or even polymorphic types. By supporting a modern type system within conversational interaction logic, it becomes easier to interact with these functions and promotes the reuse of conversational behaviors.</p><h4 id="language-perception" tabindex="-1">Language perception <a class="header-anchor" href="#language-perception" aria-label="Permalink to &quot;Language perception&quot;">​</a></h4><p>This layer is used to convert user utterances into structured representation of semantics, or frames, using natural language understanding (NLU), and generate natural text for given semantic frame using natural language generation (NLG). We need automatic speech recognition (ASR) and text to speech (TTS) to convert sound wave and back if we want to communicate with user via voice.</p><p>While recent progress in deep neural networks has made these problems much easier, there are still couple of design decisions that can greatly impact the developer experiences. The semantic space capture refers to the way in which we understand user utterances. There are two main approaches: literal meaning, which involves understanding the utterance without any context, and implied meaning, which involves interpreting the utterance based on a particular context. For example: “I have a meeting in Beijing on Tuesday morning.” can be interpreted into “{destination=beijing, time &lt; Tuesday}” by the travel agent when he hears this from his client. Clearly, use implied meaning as semantic space can reduce the effort level down the road. How do chatbot developer develop and hot fix the understanding problem? Traditionally, chatbot developer need to train a separate ML model for each chatbot, and fix the understanding under this paradigm can be extremely time-consuming. With recent advance in zero-shot learning based on large language model, it is now possible that chatbot developer can develop and hot fix understanding module without knowing how to training a machine learning model.</p><h3 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h3><p>The three-layered approach for building GUI applications has been successful and widely adopted, including on desktop, web, and mobile. We believe this same approach can be applied to building chatbots, specifically using our 3-layered CUI framework OpenCUI. OpenCUI focused on using zero-shot learning towards implied meaning, and entirely do away with training, our dogfooding have found it to be cost-effective in developing CUI’s. Give it a try today.</p>',16)]))}const f=a(r,[["render",s]]);export{g as __pageData,f as default};
